#!/usr/bin/env python3
"""Export compact real evidence, with source hashes, without reads/secrets/binaries."""
import datetime,json,pathlib,sys
ROOT=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT))
from genetrace.io import sha256
OUT=ROOT/'demo/evidence'
def source(path):return dict(path=path,sha256=sha256(ROOT/path))
def evidence(tool,title,data,paths):return dict(tool=tool,title=title,data=data,sources=[source(p) for p in paths])
def main():
 OUT.mkdir(parents=True,exist_ok=True);cases=[];audit=json.loads((ROOT/'outputs/ecoli100_candidate_audit_20261102/context.json').read_text());raw=json.loads((ROOT/'outputs/ecoli100_raw_validation_20261102/summary.json').read_text());audit_rows=json.loads((ROOT/'outputs/ecoli100_candidate_audit_20261102/results.json').read_text())
 for case_id,acc,gene,title,question in [('nimt','GCF_001558995.2','nimT','Readとassemblyの不一致 / Read–assembly 불일치','Does the nimT disagreement indicate a local assembly problem, or is the read/assembly relationship unresolved?'),('provenance','GCF_013112335.1','tonB','완벽한 read 지지도 출처 확인이 필요하다','Can these perfectly matching reads serve as independent physical sequencing validation?')]:
  context=next(r for r in audit if r['assembly']==acc and r['gene']==gene);a=next(r for r in raw['assemblies'] if r['assembly']==acc);r=next(r for r in a['regions'] if r['name']==gene);index=a['regions'].index(r);report=json.loads((ROOT/f'outputs/ecoli100_raw_validation_20261102/{acc}_{index}.json').read_text());annotation=next(r for r in audit_rows if r['assembly_accession']==acc and r['reference_gene']==gene)
  compact=dict(region=report['region'],metrics=report['metrics'],signals=report['signals'],coherent_substitutions=report['coherent_substitutions'][:12],coherent_substitution_count=len(report['coherent_substitutions']),coherent_indels=[r for r in report['indels'] if r['coherent']],variant_calls_made=False,causal_diagnosis='unresolved')
  tools=[evidence('lookup_cohort_comparison','집단·계통·주변 유전자',context,['outputs/ecoli100_candidate_audit_20261102/context.json']),evidence('inspect_annotation','DNA 상동성과 구조 주석',dict(best_genome_hit=annotation['best_genome_hit'],overlapping_cds=annotation.get('overlapping_cds'),both_flanks=annotation.get('both_flanks'),cluster_absence_is_not_gene_loss=True),['outputs/ecoli100_candidate_audit_20261102/results.json']),evidence('lookup_read_evidence','Read 출처·품질·무결성',dict(run=a['run'],whole_run_files_verified=a['whole_run_files_verified'],assembly_run_version_use_verified=False,read_provenance=a.get('read_provenance',{})),['outputs/ecoli100_raw_validation_20261102/summary.json']),evidence('lookup_regional_qc','후보와 인접 대조 구간',dict(candidate=compact,neighbor_regions=[x for x in a['regions'] if x['role']=='local_neighbor_control'],read_provenance=a.get('read_provenance',{})),[f'outputs/ecoli100_raw_validation_20261102/{acc}_{index}.json'])]
  cases.append(dict(id=case_id,title=title.replace('Readとassemblyの不一致 / ',''),assembly=acc,gene=gene,question=question,tools=tools,next_check='Verify exact run-to-assembly-version provenance and independently inspect the locus; population and read disagreements do not establish cause.'))
 fcs=json.loads((ROOT/'outputs/contamination_validation_20261102/summary.json').read_text());items=[{k:v for k,v in r.items() if k not in ['files','command','fcs_summary']} for r in fcs['evaluations']]
 cases.append(dict(id='contamination',title='NCBI 오염 양성 데이터로 한계를 확인한다',assembly='three external E. coli controls',gene='contig-level screening',question='What is supported by the FCS concordance test, and what contamination claims remain unsupported?',tools=[evidence('lookup_cohort_comparison','100개 비교 패널과 고정 기준',dict(reference_assemblies=100,thresholds=fcs['thresholds'],thresholds_tuned_to_labels=False,short_contigs_excluded=True),['outputs/contamination_validation_20261102/summary.json']),evidence('inspect_sequence','독립적인 패널 대응 검사',dict(evaluations=items,method='Population alignability flags finalized before reading external FCS spans; homologous accessory/mobile DNA and close contaminants remain unresolved.'),['outputs/contamination_validation_20261102/summary.json']),evidence('lookup_regional_qc','외부 FCS 대조와 제한',dict(evaluations=items,scope='contig-level concordance only, not span detection or diagnostic accuracy',additional_flags_are_not_confirmed_contamination=True,FCS_no_action_is_not_confirmed_negative=True),['outputs/contamination_validation_20261102/summary.json'])],next_check='Evaluate short contigs, independent negatives and accessory/mobile elements without tuning to these validation labels.'))
 for case in cases:
  case.update(evidence_mode='snapshot_of_completed_real_analyses',built_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),model_called=False)
  (OUT/(case['id']+'.json')).write_text(json.dumps(case,ensure_ascii=False,indent=2)+'\n')
 manifest=dict(cases=[dict(id=c['id'],title=c['title'],assembly=c['assembly'],gene=c['gene'],sha256=sha256(OUT/(c['id']+'.json'))) for c in cases],scope='Saved real-analysis evidence; no new alignment or model inference is implied by loading snapshots.',source_data='Public NCBI/ENA records and locally derived analyses; no raw reads or API keys included.')
 (ROOT/'demo/manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n');print('Exported',len(cases),'real evidence cases')
if __name__=='__main__':main()
